                candidates_u.sort(key=lambda u: (cap[u] - used[u], -u), reverse=True)
                for u in candidates_u:
                    if sol[i][u]:
                        continue
                    if cap[u] - used[u] >= inst.setup_time[i] - 1e-9:
                        new_sol = [list(row) for row in sol]
                        new_sol[i][u] = True
                        return tuple(tuple(row) for row in new_sol), True

        return sol, False

